<style>
  .pmr { font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #000; }
  .pmr table.hdr { width: 100%; border-collapse: collapse; margin: 0 0 6pt 0; }
  .pmr table.hdr td { border: none; padding: 0; vertical-align: middle; }
  .pmr td.hl { text-align: left;   width: 25%; font-size: 6.5pt; font-weight: bold; }
  .pmr td.hc { text-align: center; width: 50%; }
  .pmr td.hr { text-align: right;  width: 25%; font-size: 6.5pt; }
  .pmr img.logo { height: 40px; width: auto; max-width: 200px; }
  .pmr .title { font-weight: bold; font-size: 11pt; }
  .pmr .period { font-size: 8pt; margin-top: 1pt; }
  .pmr table.grid { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .pmr table.grid th, .pmr table.grid td { border: 0.5pt solid #000; padding: 1.5pt 3pt; overflow: hidden; }
  .pmr table.grid thead th { text-align: center; font-weight: bold; vertical-align: middle; background: #eaeaea; }
  .pmr table.grid thead th.band { font-size: 7.5pt; letter-spacing: 0.4pt; }
  .pmr table.grid thead th.blank { background: #fff; border-top: none; border-left: none; }
  .pmr table.grid td.num { text-align: right; }
  .pmr table.grid td.txt { text-align: left; }
  .pmr table.grid tr.total td { font-weight: bold; background: #f2f2f2; }
  .pmr .signature { margin-top: 16pt; font-size: 8pt; font-weight: bold; }
</style>

<div class="pmr">
  <table class="hdr">
    <tr>
      <td class="hl">CONFIDENTIAL</td>
      <td class="hc"></td>
      <td class="hr">{%= frappe.datetime.str_to_user(frappe.datetime.now_datetime()) %}</td>
    </tr>
    <tr>
      <td class="hl"><img class="logo" src="{%= LOGO %}"></td>
      <td class="hc">
        <div class="title">{%= TITLE %}</div>
        <div class="period">{%= f.from_date ? frappe.datetime.str_to_user(f.from_date) : "" %}{%= f.to_date ? "  to  " + frappe.datetime.str_to_user(f.to_date) : "" %}</div>
      </td>
      <td class="hr"></td>
    </tr>
  </table>

  <table class="grid">
    <thead>
      {% if (SHOW_BANDS) { %}
      <tr>
        <th class="blank" colspan="3"></th>
        <th class="band" colspan="4">SALARY &amp; ALLOWANCES</th>
        <th class="band" colspan="7">DEDUCTIONS</th>
        <th class="band" colspan="3">TAKE HOME PAY</th>
      </tr>
      {% } %}
      <tr>
        {% for (var j = 0; j < cols.length; j++) { %}
        <th style="width:{%= cols[j].width || 100 %}px">{%= cols[j].label %}</th>
        {% } %}
      </tr>
    </thead>
    <tbody>
      {% for (var i = 0; i < rows.length; i++) { %}
        {% var r = rows[i]; %}
        {% var isTotal = (cols.length > 2) && !r[cols[2].fieldname]; %}
        <tr class="{%= isTotal ? 'total' : '' %}">
          {% for (var j = 0; j < cols.length; j++) { %}
            {% var c = cols[j]; %}
            {% if (j < TEXT_COLS) { %}
              <td class="txt">{%= (isTotal && j === 0) ? "TOTAL" : (isTotal ? "" : val(r, c)) %}</td>
            {% } else { %}
              <td class="num">{%= money(val(r, c)) %}</td>
            {% } %}
          {% } %}
        </tr>
      {% } %}
    </tbody>
  </table>

  <div class="signature">APPROVED BY MANAGING DIRECTOR .............................................................................</div>
</div>

