{%- set nsra = namespace(ra_e=0.0, ra_d=0.0, folded=false) -%}
{%- for row in doc.earnings %}{% if row.salary_component == 'Reconciliation Adjustment' %}{% set nsra.ra_e = nsra.ra_e + row.amount %}{% endif %}{% endfor -%}
{%- for row in doc.deductions %}{% if row.salary_component == 'Reconciliation Adjustment - Deduction' %}{% set nsra.ra_d = nsra.ra_d + row.amount %}{% endif %}{% endfor -%}
{%- set earnings_raw = doc.earnings | selectattr("statistical_component", "equalto", 0) | selectattr("do_not_include_in_total", "equalto", 0) | rejectattr("salary_component", "equalto", "Reconciliation Adjustment") | list -%}
{%- set deductions_raw = doc.deductions | selectattr("statistical_component", "equalto", 0) | selectattr("do_not_include_in_total", "equalto", 0) | rejectattr("salary_component", "equalto", "Reconciliation Adjustment - Deduction") | list -%}
{%- set earnings = [] -%}
{%- for row in earnings_raw -%}
  {%- if row.salary_component == 'Extra Duty Allowance' and nsra.ra_e -%}
    {%- set _ = earnings.append({'salary_component': row.salary_component, 'amount': row.amount + nsra.ra_e}) -%}
    {%- set nsra.folded = true -%}
  {%- else -%}
    {%- set _ = earnings.append({'salary_component': row.salary_component, 'amount': row.amount}) -%}
  {%- endif -%}
{%- endfor -%}
{%- if nsra.ra_e and not nsra.folded -%}
  {%- set _ = earnings.append({'salary_component': 'Other Allowance', 'amount': nsra.ra_e}) -%}
{%- endif -%}
{%- set deductions = [] -%}
{%- for row in deductions_raw -%}
  {%- set _ = deductions.append({'salary_component': row.salary_component, 'amount': row.amount}) -%}
{%- endfor -%}
{%- if nsra.ra_d -%}
  {%- set _ = deductions.append({'salary_component': 'Other Deductions', 'amount': nsra.ra_d}) -%}
{%- endif -%}
{%- set employer = (doc.earnings | selectattr("do_not_include_in_total", "equalto", 1) | list) + (doc.deductions | selectattr("do_not_include_in_total", "equalto", 1) | list) -%}
