<style>
  .bgl { font-family: Arial, Helvetica, sans-serif; font-size: 8pt; color: #000; }
  .bgl table.hdr { width: 100%; border-collapse: collapse; margin: 0 0 6pt 0; }
  .bgl table.hdr td { border: none; padding: 0; vertical-align: middle; }
  .bgl td.hl { text-align: left; width: 25%; font-size: 6.5pt; font-weight: bold; }
  .bgl td.hc { text-align: center; width: 50%; }
  .bgl td.hr { text-align: right; width: 25%; font-size: 6.5pt; }
  .bgl img.logo { height: 40px; width: auto; max-width: 200px; }
  .bgl .title { font-weight: bold; font-size: 11pt; }
  .bgl .period { font-size: 8pt; margin-top: 1pt; }
  .bgl table.grid { width: 100%; border-collapse: collapse; }
  .bgl table.grid th, .bgl table.grid td { border: 0.5pt solid #000; padding: 2pt 3pt; }
  .bgl table.grid thead th { text-align: center; font-weight: bold; background: #eaeaea; font-size: 7.5pt; }
  .bgl td.num { text-align: right; }
  .bgl tr.total td { font-weight: bold; background: #f2f2f2; }
  .bgl .signature { margin-top: 16pt; font-size: 8pt; font-weight: bold; }
</style>
<div class="bgl">
  <table class="hdr">
    <tr><td class="hl">CONFIDENTIAL</td><td class="hc"></td>
        <td class="hr">{%= frappe.datetime.str_to_user(frappe.datetime.now_datetime()) %}</td></tr>
    <tr>
      <td class="hl"><img class="logo" src="/files/betonsa_logo.jpeg"></td>
      <td class="hc">
        <div class="title">TRIP AND CUBIC COSTING REPORT</div>
        <div class="period">{%= f.from_date ? frappe.datetime.str_to_user(f.from_date) : "" %}{%= f.to_date ? "  to  " + frappe.datetime.str_to_user(f.to_date) : "" %}{%= f.site ? "   |   Site: " + f.site : "" %}{%= f.scope ? "   |   " + f.scope : "" %}</div>
      </td>
      <td class="hr"></td>
    </tr>
  </table>
  <table class="grid">
    <thead><tr>
      {% for (var j = 0; j < cols.length; j++) { %}<th>{%= cols[j].label %}</th>{% } %}
    </tr></thead>
    <tbody>
      {% for (var i = 0; i < rows.length; i++) { %}
        {% var r = rows[i]; if (Array.isArray(r)) continue; %}
        <tr>
          {% for (var j = 0; j < cols.length; j++) { %}
            {% var c = cols[j]; var v = r[c.fieldname]; %}
            {% if (numtypes[c.fieldtype]) { %}
              {% totals[c.fieldname] = (totals[c.fieldname] || 0) + flt(v); %}
              <td class="num">{%= v ? format_number(flt(v), null, c.fieldtype === "Int" ? 0 : 2) : "-" %}</td>
            {% } else { %}
              <td>{%= (v === undefined || v === null) ? "" : v %}</td>
            {% } %}
          {% } %}
        </tr>
      {% } %}
      <tr class="total">
        {% for (var j = 0; j < cols.length; j++) { %}
          {% var c = cols[j]; %}
          {% if (j === 0) { %}<td>TOTAL</td>{% } else if (numtypes[c.fieldtype]) { %}
            <td class="num">{%= format_number(totals[c.fieldname] || 0, null, c.fieldtype === "Int" ? 0 : 2) %}</td>
          {% } else { %}<td></td>{% } %}
        {% } %}
      </tr>
    </tbody>
  </table>
  <div class="signature">PREPARED BY (HR) ....................................  APPROVED BY MANAGING DIRECTOR ....................................</div>
</div>

